    uint8_t* _content;
    uint32_t _content_len;
    blosc2_get_metalayer(schunk, "metalayer1", &_content, &_content_len);
    mu_assert("ERROR: bad metalayer content", strncmp((char*)_content, "my metalayer1", _content_len) == 0);
