   573	/* Create a frame out of a super-chunk. */
   574	int64_t blosc2_frame_from_schunk(blosc2_schunk *schunk, blosc2_frame *frame) {
   575	  int32_t nchunks = schunk->nchunks;
   576	  int64_t cbytes = schunk->cbytes;
   577	  FILE* fp = NULL;
   578	
   579	  uint8_t* h2 = new_header_frame(schunk, frame);
   580	  if (h2 == NULL) {
   581	    return -1;
   582	  }
   583	  uint32_t h2len;
   584	  swap_store(&h2len, h2 + FRAME_HEADER_LEN, sizeof(h2len));
   585	
   586	  // Build the offsets chunk
   587	  int32_t chunksize = -1;
   588	  int32_t off_cbytes = 0;
   589	  uint64_t coffset = 0;
   590	  int32_t off_nbytes = nchunks * 8;
   591	  uint64_t* data_tmp = malloc(off_nbytes);
   592	  for (int i = 0; i < nchunks; i++) {
   593	    uint8_t* data_chunk = schunk->data[i];
   594	    int32_t chunk_cbytes = sw32_(data_chunk + BLOSC2_CHUNK_CBYTES);
   595	    data_tmp[i] = coffset;
   596	    coffset += chunk_cbytes;
   597	    int32_t chunksize_ = sw32_(data_chunk + BLOSC2_CHUNK_NBYTES);
   598	    if (i == 0) {
   599	      chunksize = chunksize_;
   600	    }
   601	    else if (chunksize != chunksize_) {
   602	      // Variable size  // TODO: update flags for this (or do not use them at all)
   603	      chunksize = 0;
   604	    }
   605	  }
   606	  if ((int64_t)coffset != cbytes) {
   607	    return -1;
   608	  }
   609	
   610	  uint8_t *off_chunk = NULL;
   611	  if (nchunks > 0) {
   612	    // Compress the chunk of offsets
   613	    off_chunk = malloc(off_nbytes + BLOSC_MAX_OVERHEAD);
   614	    blosc2_context *cctx = blosc2_create_cctx(BLOSC2_CPARAMS_DEFAULTS);
   615	    cctx->typesize = 8;
   616	    off_cbytes = blosc2_compress_ctx(cctx, data_tmp, off_nbytes, off_chunk,
   617	                                     off_nbytes + BLOSC_MAX_OVERHEAD);
   618	    blosc2_free_ctx(cctx);
   619	    if (off_cbytes < 0) {
   620	      free(off_chunk);
   621	      free(h2);
   622	      return -1;
   623	    }
   624	  }
   625	  else {
   626	    off_cbytes = 0;
   627	  }
   628	  free(data_tmp);
   629	
   630	  // Now that we know them, fill the chunksize and frame length in header
   631	  swap_store(h2 + FRAME_CHUNKSIZE, &chunksize, sizeof(chunksize));
   632	  frame->len = h2len + cbytes + off_cbytes + FRAME_TRAILER_MINLEN + schunk->usermeta_len;
   633	  int64_t tbytes = frame->len;
   634	  swap_store(h2 + FRAME_LEN, &tbytes, sizeof(tbytes));
   635	
   636	  // Create the frame and put the header at the beginning
   637	  if (frame->fname == NULL) {
   638	    frame->sdata = malloc((size_t)frame->len);
   639	    memcpy(frame->sdata, h2, h2len);
   640	  }
   641	  else {
   642	    fp = fopen(frame->fname, "wb");
   643	    fwrite(h2, h2len, 1, fp);
   644	  }
   645	  free(h2);
   646	
   647	  // Fill the frame with the actual data chunks
   648	  coffset = 0;
   649	  for (int i = 0; i < nchunks; i++) {
   650	    uint8_t* data_chunk = schunk->data[i];
   651	    int32_t chunk_cbytes = sw32_(data_chunk + BLOSC2_CHUNK_CBYTES);
   652	    if (frame->fname == NULL) {
   653	      memcpy(frame->sdata + h2len + coffset, data_chunk, (size_t)chunk_cbytes);
   654	    } else {
   655	      fwrite(data_chunk, (size_t)chunk_cbytes, 1, fp);
   656	    }
   657	    coffset += chunk_cbytes;
   658	  }
   659	  if ((int64_t)coffset != cbytes) {
   660	    return -1;
   661	  }
   662	
   663	  // Copy the offsets chunk at the end of the frame
   664	  if (frame->fname == NULL) {
   665	    memcpy(frame->sdata + h2len + cbytes, off_chunk, off_cbytes);
   666	  }
   667	  else {
   668	    fwrite(off_chunk, (size_t)off_cbytes, 1, fp);
   669	    fclose(fp);
   670	  }
   671	  free(off_chunk);
   672	
   673	  int rc = frame_update_trailer(frame, schunk);
   674	  if (rc < 0) {
   675	    return rc;
   676	  }
   677	
   678	  return frame->len;
   679	}
